// Special cases
if (text.empty()) {  // !text
  return "";
}
const std::string& key = text;  // text.toString()
// ii: root?.translations?. 的 ?. 不生效：两个属性恒为对象（这里是 map），hasOwnProperty 即 contains
// ii: isLoading 从不被设为 true，这个条件实际只看两个表里有没有 key
if (this->isLoading.get() || (!this->translations.get().contains(key) && !this->generatedTranslations.get().contains(key))) {
  return key;
}

// Normal cases
// translations[key] || generatedTranslations[key] || key：缺失（undefined）和 "" 都为假
const auto lookup = [&key](const std::map<std::string, std::string>& table) -> std::string {
  const auto it = table.find(key);
  return it == table.end() ? std::string() : it->second;
};
std::string translation = lookup(this->translations.get());
if (translation.empty()) {
  translation = lookup(this->generatedTranslations.get());
}
if (translation.empty()) {
  translation = key;
}
const std::string& keepSuffix = this->translationKeepSuffix.get();
if (js::endsWith(translation, keepSuffix)) {
  translation = js::trim(js::substring(translation, 0, js::length(translation) - js::length(keepSuffix)));
}
return translation;

